SOCIAL_SCHEMA="""
CREATE TABLE IF NOT EXISTS user_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id),bio TEXT NOT NULL DEFAULT '',privacy TEXT NOT NULL DEFAULT '{"bio":"public","message":"public","presence":"public","work_status":"public","location":"public"}');
CREATE TABLE IF NOT EXISTS friend_requests(id TEXT PRIMARY KEY,sender_id TEXT NOT NULL REFERENCES users(id),recipient_id TEXT NOT NULL REFERENCES users(id),user_low TEXT NOT NULL,user_high TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','accepted','rejected','cancelled')),created_at REAL NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS pending_friend_pair ON friend_requests(user_low,user_high) WHERE status='pending';
CREATE TABLE IF NOT EXISTS friendships(user_low TEXT NOT NULL REFERENCES users(id),user_high TEXT NOT NULL REFERENCES users(id),created_at REAL NOT NULL,PRIMARY KEY(user_low,user_high));
CREATE TABLE IF NOT EXISTS user_blocks(user_id TEXT NOT NULL REFERENCES users(id),blocked_id TEXT NOT NULL REFERENCES users(id),created_at REAL NOT NULL,PRIMARY KEY(user_id,blocked_id));
CREATE TABLE IF NOT EXISTS social_groups(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,description TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN ('private','public')),max_members INTEGER NOT NULL CHECK(max_members BETWEEN 2 AND 50),cover_media_id TEXT,deleted INTEGER NOT NULL DEFAULT 0,created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS group_memberships(group_id TEXT NOT NULL REFERENCES social_groups(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('owner','manager','member')),created_at REAL NOT NULL,PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS group_invitations(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES social_groups(id),sender_id TEXT NOT NULL REFERENCES users(id),recipient_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN ('invite','request')),status TEXT NOT NULL CHECK(status IN ('pending','accepted','rejected','cancelled')),created_at REAL NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS pending_group_invite ON group_invitations(group_id,recipient_id,kind) WHERE status='pending';
CREATE TABLE IF NOT EXISTS shared_logs(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES social_groups(id),author_id TEXT NOT NULL REFERENCES users(id),text TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN ('group','self')),deleted INTEGER NOT NULL DEFAULT 0,hidden INTEGER NOT NULL DEFAULT 0,created_at REAL NOT NULL,updated_at REAL NOT NULL);
CREATE INDEX IF NOT EXISTS logs_group_created ON shared_logs(group_id,created_at,id);
CREATE TABLE IF NOT EXISTS log_media(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),log_id TEXT REFERENCES shared_logs(id),group_id TEXT REFERENCES social_groups(id),storage_key TEXT NOT NULL,content_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,deleted INTEGER NOT NULL DEFAULT 0,created_at REAL NOT NULL);
CREATE INDEX IF NOT EXISTS media_owner ON log_media(owner_id,created_at);
CREATE TABLE IF NOT EXISTS log_comments(id TEXT PRIMARY KEY,log_id TEXT NOT NULL REFERENCES shared_logs(id),author_id TEXT NOT NULL REFERENCES users(id),text TEXT NOT NULL,deleted INTEGER NOT NULL DEFAULT 0,hidden INTEGER NOT NULL DEFAULT 0,created_at REAL NOT NULL,updated_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS log_reactions(target_kind TEXT NOT NULL CHECK(target_kind IN ('log','comment')),target_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),emoji TEXT NOT NULL CHECK(emoji IN ('like','heart','laugh','cheer')),created_at REAL NOT NULL,PRIMARY KEY(target_kind,target_id,user_id,emoji));
CREATE TABLE IF NOT EXISTS user_notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),actor_id TEXT REFERENCES users(id),kind TEXT NOT NULL,group_id TEXT REFERENCES social_groups(id),log_id TEXT REFERENCES shared_logs(id),reference_id TEXT,message TEXT NOT NULL,read_at REAL,created_at REAL NOT NULL);
CREATE INDEX IF NOT EXISTS notifications_owner ON user_notifications(user_id,created_at);
CREATE TABLE IF NOT EXISTS content_reports(id TEXT PRIMARY KEY,reporter_id TEXT NOT NULL REFERENCES users(id),target_kind TEXT NOT NULL CHECK(target_kind IN ('log','comment','user')),target_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',resolution TEXT NOT NULL DEFAULT '',resolved_by TEXT REFERENCES users(id),created_at REAL NOT NULL,resolved_at REAL);
"""
